def svg(nombre: str, clase: str = "ico", etiqueta: str = "") -> str:
    """El SVG del ícono. Con `etiqueta`, se anuncia a los lectores de pantalla;
    sin ella es decorativo (aria-hidden)."""
    trazo = ICONOS.get(nombre, ICONOS["info"])
    accesible = f'role="img" aria-label="{etiqueta}"' if etiqueta else 'aria-hidden="true" focusable="false"'
    return (f'<svg class="{clase}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" '
            f'stroke-linecap="round" stroke-linejoin="round" {accesible}>{trazo}</svg>')
